const finish = (rows, returned) => rows.map(row=>{
  const missing=Object.keys(row).filter(k=>row[k]==null);
  const output={...row,...common,returned_count:returned,exported_count:rows.length,missing_fields:missing.join(';')};
  return {json:Object.fromEntries(Object.entries(output).map(([k,v])=>[k,cell(v)]))};
});
const t=d.transcript;
if(!t || !Array.isArray(t.segments))throw new Error('No transcript segments.');
const languageCode = value => {
 if(typeof value!=='string')return null;
 const v=value.trim().toLowerCase().replace(/_/g,'-');
 if(v==='english')return 'en';
