};
const returnedLanguage=languageCode(t.language);
if(!returnedLanguage || returnedLanguage!==languageCode(request.language))throw new Error('Returned caption language differs from request or is unknown; review before exporting.');
const rows=[];const seen=new Set();
for(const s of t.segments.slice(0,100)) {
 if(!s || typeof s.text!=='string' || !s.text.trim() || !Number.isFinite(s.startMs) || !Number.isFinite(s.endMs) || s.startMs<0 || s.endMs<s.startMs)throw new Error('Invalid caption segment.');
 const id=request.url+'|'+s.startMs+'|'+s.endMs;if(seen.has(id))continue;seen.add(id);
 const videoId=request.url.match(/[?&]v=([A-Za-z0-9_-]{11})(?:[&#]|$)/)?.[1] ?? request.url.match(/^https:\/\/youtu\.be\/([A-Za-z0-9_-]{11})(?:[?#]|$)/)?.[1];
 if(!videoId)throw new Error('Expected a watch or youtu.be URL with an 11-character video ID.');
